import json
from itertools import permutations

def solve_puzzle():
    # Houses numbered from left (1) to right (3)
    houses = [1, 2, 3]

    # Attributes as given
    names = ["Eric", "Arnold", "Peter"]
    phone_models = ["iphone 13", "samsung galaxy s21", "google pixel 6"]
    heights = ["very short", "average", "short"]
    house_styles = ["colonial", "ranch", "victorian"]
    car_models = ["tesla model 3", "toyota camry", "ford f150"]

    solutions = []

    # Enumerate permutations with early pruning based on constraints
    for name_perm in permutations(names):
        # 7. Arnold is in the second house.
        if name_perm[1] != "Arnold":
            continue
        # 1. Peter is somewhere to the right of Eric.
        if name_perm.index("Peter") <= name_perm.index("Eric"):
            continue

        for style_perm in permutations(house_styles):
            # 2. The person living in a colonial-style house is in the second house.
            if style_perm[1] != "colonial":
                continue
            # 6. Colonial is somewhere to the right of the ranch-style home.
            if style_perm.index("colonial") <= style_perm.index("ranch"):
                continue

            for height_perm in permutations(heights):
                # 9. The person who has an average height is in the first house.
                if height_perm[0] != "average":
                    continue

                for phone_perm in permutations(phone_models):
                    # 5. iPhone 13 is directly left of Google Pixel 6.
                    if phone_perm.index("iphone 13") + 1 != phone_perm.index("google pixel 6"):
                        continue
                    # 4. The person who is short is directly left of the person who uses a Samsung Galaxy S21.
                    if height_perm.index("short") + 1 != phone_perm.index("samsung galaxy s21"):
                        continue

                    for car_perm in permutations(car_models):
                        # 8. Ford F-150 is somewhere to the right of Toyota Camry.
                        if car_perm.index("ford f150") <= car_perm.index("toyota camry"):
                            continue
                        # 3. Tesla Model 3 owner is very short.
                        if car_perm.index("tesla model 3") != height_perm.index("very short"):
                            continue

                        # If all constraints satisfied, record solution
                        rows = []
                        for i in range(3):
                            rows.append([
                                str(i + 1),
                                name_perm[i],
                                phone_perm[i],
                                height_perm[i],
                                style_perm[i],
                                car_perm[i]
                            ])
                        solutions.append(rows)

    # Assuming a unique solution for this puzzle
    if not solutions:
        raise RuntimeError("No solution found.")
    result_rows = solutions[0]

    output = {
        "solution": {
            "header": ["House", "name", "phone models", "heights", "style of house", "car models"],
            "rows": result_rows
        }
    }
    print(json.dumps(output, ensure_ascii=False, indent=2))

if __name__ == "__main__":
    solve_puzzle()
